static std::uint64_t next_random(){auto x=random_state;x^=x<<13;x^=x>>7;x^=x<<17;return random_state=x;}
struct Query{std::int64_t n,k;};
int main(int argc,char**argv){
 std::ifstream config(argv[1]);std::string name,pattern;std::uint32_t mod,limit,initial;std::int64_t prepare;unsigned count,distinct;std::uint64_t kval,budget,base;
 while(config>>name>>mod>>limit>>initial>>prepare>>count>>pattern>>kval>>distinct>>budget>>base){
  random_state=base;std::vector<Query> queries;queries.reserve(count);std::vector<Query> seeds;std::unordered_set<std::uint64_t> seen;
  const auto nmax=static_cast<std::uint64_t>(std::numeric_limits<std::int64_t>::max());
  for(unsigned i=0;i<count;++i){
   if(i>=distinct){queries.push_back(seeds[i%distinct]);continue;}
   std::uint64_t n,k;
   if(pattern=="nmax"){n=nmax-next_random()%8000000;k=kval;}
   else if(pattern=="near"){n=static_cast<std::uint64_t>(mod)-64+next_random()%129;k=kval;}
   else if(pattern=="randomlarge"){n=next_random()&nmax;k=n/2;}
   else if(pattern=="nonzero"){n=base-1;k=kval;}
   else if(pattern=="fixed"){n=base;k=kval;}
   else {auto range=std::min<std::uint64_t>(limit,mod-1);n=next_random()%(range+1);k=next_random()%(n+1);}
   if(pattern=="prepared"&&!seen.insert(n*(n+1)/2+k).second){--i;continue;}
   Query q{static_cast<std::int64_t>(n),static_cast<std::int64_t>(k)};seeds.push_back(q);queries.push_back(q);
  }
  seen.clear();seen.rehash(0);
  BinomialOptions options;options.table_limit=limit;options.max_multiplicative_steps=budget;
  const auto a=Clock::now();BinomialMod b(mod,initial,options);const auto c=Clock::now();
